"""Lineage path explanation and impact-scope queries.

The public entry points are :func:`explain_lineage_paths` (node-level graph,
same shape as :func:`data_quality.trace_lineage`) and
:func:`explain_field_lineage_paths` (table/column graph, same shape as
:func:`data_quality.trace_field_lineage`). Edges point from ``source`` to
``target``: upstream paths follow edges backwards from the target to its
sources, downstream paths follow them forwards to every directly and
indirectly dependent object.

Unlike the breadth-first trace, every simple path is enumerated, so a node
may appear in several paths while a single path never repeats a node; a
back-edge to a node already on the current path closes a cycle and is
reported instead of being followed forever.

Graph structure problems and bad query arguments reuse the existing
exceptions (and therefore their CLI error codes). A target that is not
declared in the graph raises :class:`LineageNodeNotFoundError`, whose
:attr:`LineageNodeNotFoundError.code` is ``"LINEAGE_NODE_NOT_FOUND"``.
"""

from __future__ import annotations

from typing import Any, Dict, Generic, List, Optional, Tuple, TypeVar

from . import field_lineage as _field_lineage
from . import lineage as _lineage

__all__ = [
    "explain_lineage_paths",
    "explain_field_lineage_paths",
    "LineageNodeNotFoundError",
]

VALID_DIRECTIONS = _lineage.VALID_DIRECTIONS

Node = TypeVar("Node")

# A path is carried as (nodes in traversal order, edge ids in traversal
# order). An edge id is a (source, target) pair of node ids.
_Path = Tuple[Tuple[Any, ...], Tuple[Tuple[Any, Any], ...]]


class LineageNodeNotFoundError(ValueError):
    """The queried target node is not declared in the graph."""

    code = "LINEAGE_NODE_NOT_FOUND"


def _validate_max_depth(max_depth: Any) -> None:
    if max_depth is not None:
        # bool is a subclass of int, but JSON true/false are not depths.
        if isinstance(max_depth, bool) or not isinstance(max_depth, int):
            raise ValueError("max_depth must be null or an integer >= 0")
        if max_depth < 0:
            raise ValueError(f"max_depth must be >= 0, got {max_depth}")


class _PathQuery(Generic[Node]):
    """All-simple-paths enumeration plus cycle reporting for one graph.

    ``neighbors`` maps each node to the ``(edge_id, next_node)`` pairs that
    lead in the queried traversal direction. ``edge_id`` is the directed
    (source, target) pair of the original edge, regardless of traversal
    direction.
    """

    def __init__(
        self,
        neighbors: Dict[Node, List[Tuple[Tuple[Any, Any], Node]]],
        max_depth: Optional[int],
    ) -> None:
        self._neighbors = neighbors
        self._max_depth = max_depth

    def run(
        self, start: Node
    ) -> Tuple[List[_Path], List[Node], List[Tuple[Any, Any]]]:
        paths: List[_Path] = []
        cycle_nodes_set: set = set()
        cycle_edges_set: set = set()

        def visit(
            route_nodes: List[Node], route_edges: List[Tuple[Any, Any]]
        ) -> None:
            current = route_nodes[-1]
            depth = len(route_edges)
            if self._max_depth is not None and depth >= self._max_depth:
                paths.append((tuple(route_nodes), tuple(route_edges)))
                return

            steps = self._neighbors.get(current)
            if not steps:
                paths.append((tuple(route_nodes), tuple(route_edges)))
                return

            for edge_id, nxt in steps:
                if nxt in route_nodes:
                    # Back-edge to a node on the current path: this is the
                    # edge that closes a cycle. The path segment already
                    # found stays in ``paths`` (emitted when its terminal
                    # node finished expanding); the cycle itself is recorded
                    # without following the edge, so no path can grow
                    # through the loop forever.
                    cycle_nodes_set.add(nxt)
                    cycle_edges_set.add(edge_id)
                    continue
                route_nodes.append(nxt)
                route_edges.append(edge_id)
                visit(route_nodes, route_edges)
                route_nodes.pop()
                route_edges.pop()

        visit([start], [])
        return paths, list(cycle_nodes_set), list(cycle_edges_set)


def _sort_paths(paths: List[_Path]) -> List[_Path]:
    return sorted(
        paths,
        key=lambda path: (len(path[1]), path[0], path[1]),
    )


def _node_level_query(
    nodes: Any,
    edges: Any,
    target: Any,
    direction: Any,
    max_depth: Any,
) -> Tuple[str, List[Dict[str, str]], Dict[str, Any]]:
    """Validate and prepare a node-level query.

    Returns the start node id, the original edge dicts and the common query
    state. Graph/query validation deliberately reuses the lineage module's
    validators so its accepted inputs and error semantics stay identical.
    """
    declared = _lineage._validate_graph(nodes, edges)
    _lineage._validate_query(target, direction, None)
    _validate_max_depth(max_depth)

    if target not in declared:
        raise LineageNodeNotFoundError(
            f"target is not declared in nodes: {target!r}"
        )

    outgoing, incoming = _lineage._build_adjacency(edges)

    def directed(neighbors: Dict[str, List[str]]) -> Dict[str, List[Tuple[Tuple[str, str], str]]]:
        adjacency: Dict[str, List[Tuple[Tuple[str, str], str]]] = {}
        for node_id, linked in neighbors.items():
            steps: List[Tuple[Tuple[str, str], str]] = []
            for other in linked:
                if neighbors is incoming:
                    edge_id = (other, node_id)
                else:
                    edge_id = (node_id, other)
                steps.append((edge_id, other))
            adjacency[node_id] = steps
        return adjacency

    return target, edges, {
        "upstream_neighbors": directed(incoming)
        if direction in ("upstream", "both")
        else None,
        "downstream_neighbors": directed(outgoing)
        if direction in ("downstream", "both")
        else None,
    }


def _field_level_query(
    fields: Any,
    edges: Any,
    target: Any,
    direction: Any,
    max_depth: Any,
) -> Tuple[Any, List[Dict[str, Any]], Dict[str, Any]]:
    """Validate and prepare a table/column-level query."""
    declared = _field_lineage._validate_fields(fields)
    _field_lineage._validate_edges(edges, declared)
    _field_lineage._validate_query(target, direction, None)
    _validate_max_depth(max_depth)

    start = _field_lineage._field_id(target)
    if start not in declared:
        raise LineageNodeNotFoundError(
            f"target is not declared in fields: {target!r}"
        )

    outgoing, incoming = _field_lineage._build_adjacency(edges)

    def directed(
        neighbors: Dict[Any, List[Any]]
    ) -> Dict[Any, List[Tuple[Tuple[Any, Any], Any]]]:
        adjacency: Dict[Any, List[Tuple[Tuple[Any, Any], Any]]] = {}
        for field_id, linked in neighbors.items():
            steps: List[Tuple[Tuple[Any, Any], Any]] = []
            for other in linked:
                if neighbors is incoming:
                    edge_id = (other, field_id)
                else:
                    edge_id = (field_id, other)
                steps.append((edge_id, other))
            adjacency[field_id] = steps
        return adjacency

    return start, edges, {
        "upstream_neighbors": directed(incoming)
        if direction in ("upstream", "both")
        else None,
        "downstream_neighbors": directed(outgoing)
        if direction in ("downstream", "both")
        else None,
    }


def _edge_lookup(edges: List[Dict[str, Any]]) -> Dict[Tuple[Any, Any], Dict[str, Any]]:
    lookup: Dict[Tuple[Any, Any], Dict[str, Any]] = {}
    for edge in edges:
        source = edge["source"]
        target = edge["target"]
        if isinstance(source, str):
            key = (source, target)
        else:
            key = (
                (source["table"], source["column"]),
                (target["table"], target["column"]),
            )
        lookup[key] = edge
    return lookup


def _build_node_side(
    start: str,
    edges: List[Dict[str, str]],
    neighbors: Optional[Dict[str, List[Tuple[Tuple[str, str], str]]]],
    max_depth: Optional[int],
) -> Dict[str, Any]:
    if neighbors is None:
        return {"paths": [], "cycle": False, "cycle_nodes": [], "cycle_edges": []}

    raw_paths, cycle_nodes, cycle_edges = _PathQuery(neighbors, max_depth).run(start)
    ordered = _sort_paths(raw_paths)
    edge_by_id = _edge_lookup(edges)

    paths: List[Dict[str, Any]] = []
    for route_nodes, route_edges in ordered:
        steps: List[Dict[str, Any]] = []
        for position, (node_id, edge_id) in enumerate(
            zip(route_nodes, [None, *route_edges])
        ):
            entry: Dict[str, Any] = {
                "node": {"id": node_id, "depth": position},
            }
            if edge_id is not None:
                entry["edge"] = dict(edge_by_id[edge_id])
            else:
                entry["edge"] = None
            steps.append(entry)
        paths.append({"nodes": steps, "depth": len(route_edges)})

    return {
        "paths": paths,
        "cycle": bool(cycle_edges),
        "cycle_nodes": sorted(cycle_nodes),
        "cycle_edges": [dict(edge_by_id[eid]) for eid in sorted(cycle_edges)],
    }


def _build_field_side(
    start: Tuple[str, str],
    edges: List[Dict[str, Any]],
    neighbors: Optional[
        Dict[Tuple[str, str], List[Tuple[Tuple[Any, Any], Tuple[str, str]]]]
    ],
    max_depth: Optional[int],
) -> Dict[str, Any]:
    if neighbors is None:
        return {"paths": [], "cycle": False, "cycle_nodes": [], "cycle_edges": []}

    raw_paths, cycle_nodes, cycle_edges = _PathQuery(neighbors, max_depth).run(start)
    ordered = _sort_paths(raw_paths)
    edge_by_id = _edge_lookup(edges)

    def field_ref(field_id: Tuple[str, str]) -> Dict[str, str]:
        return {"table": field_id[0], "column": field_id[1]}

    paths: List[Dict[str, Any]] = []
    for route_nodes, route_edges in ordered:
        steps: List[Dict[str, Any]] = []
        for position, (field_id, edge_id) in enumerate(
            zip(route_nodes, [None, *route_edges])
        ):
            entry: Dict[str, Any] = {
                "node": {
                    "table": field_id[0],
                    "column": field_id[1],
                    "depth": position,
                },
            }
            if edge_id is not None:
                original = edge_by_id[edge_id]
                entry["edge"] = {
                    "source": dict(original["source"]),
                    "target": dict(original["target"]),
                }
            else:
                entry["edge"] = None
            steps.append(entry)
        paths.append({"nodes": steps, "depth": len(route_edges)})

    return {
        "paths": paths,
        "cycle": bool(cycle_edges),
        "cycle_nodes": [field_ref(fid) for fid in sorted(cycle_nodes)],
        "cycle_edges": [
            {
                "source": dict(edge_by_id[eid]["source"]),
                "target": dict(edge_by_id[eid]["target"]),
            }
            for eid in sorted(cycle_edges)
        ],
    }


def explain_lineage_paths(
    nodes: Any,
    edges: Any,
    target: Any,
    direction: Any = "both",
    max_depth: Any = None,
) -> Dict[str, Any]:
    """Explain the concrete upstream source paths and downstream impact of
    ``target`` over a node-level lineage graph.

    :param nodes: non-empty list of distinct non-empty node id strings,
        exactly as accepted by :func:`data_quality.trace_lineage`.
    :param edges: list of ``{"source": ..., "target": ...}`` objects whose
        endpoints are declared in ``nodes``; duplicate edges are rejected.
    :param target: node id to explain; the first node of every returned
        path.
    :param direction: ``"upstream"``, ``"downstream"`` or ``"both"``
        (default ``"both"``).
    :param max_depth: ``None`` for unlimited (default) or an integer ``>= 0``
        bounding the number of edges in each path; ``0`` yields the single
        target-only path. Booleans are not integers here.
    :returns: ``{"target", "direction", "max_depth",
        "upstream": {"paths", "cycle", "cycle_nodes", "cycle_edges"},
        "downstream": {...}}``. Every path step is
        ``{"node": {"id", "depth"}, "edge": <original edge or null>}`` and
        paths are sorted by ``(edge count, node ids, edge ids)`` so repeated
        queries are byte-stable. The target existing without relations in a
        direction is a normal success with ``paths: []`` ... only an
        undeclared target is an error.
    :raises ValueError: the existing ``InvalidLineageInputError`` /
        ``InvalidLineageQueryError`` for malformed graphs or queries, and
        :class:`LineageNodeNotFoundError`
        (``code == "LINEAGE_NODE_NOT_FOUND"``) for an undeclared target.
    """
    start, edge_dicts, prepared = _node_level_query(
        nodes, edges, target, direction, max_depth
    )
    return {
        "target": start,
        "direction": direction,
        "max_depth": max_depth,
        "upstream": _build_node_side(
            start, edge_dicts, prepared["upstream_neighbors"], max_depth
        ),
        "downstream": _build_node_side(
            start, edge_dicts, prepared["downstream_neighbors"], max_depth
        ),
    }


def explain_field_lineage_paths(
    fields: Any,
    edges: Any,
    target: Any,
    direction: Any = "both",
    max_depth: Any = None,
) -> Dict[str, Any]:
    """Explain the concrete upstream source paths and downstream impact of
    ``target`` over a table/column field-level lineage graph.

    :param fields: object mapping non-empty table ids to lists of distinct
        non-empty field ids, exactly as accepted by
        :func:`data_quality.trace_field_lineage`.
    :param edges: list of ``{"source": ..., "target": ...}`` objects whose
        endpoints are ``{"table", "column"}`` objects declared in
        ``fields``; duplicate edges are rejected, self-loops and cycles are
        legal.
    :param target: ``{"table", "column"}`` field to explain.
    :param direction: ``"upstream"``, ``"downstream"`` or ``"both"``
        (default ``"both"``).
    :param max_depth: ``None`` for unlimited (default) or an integer ``>= 0``
        bounding the number of edges in each path; ``0`` yields the single
        target-only path. Booleans are not integers here.
    :returns: ``{"target", "direction", "max_depth",
        "upstream": {"paths", "cycle", "cycle_nodes", "cycle_edges"},
        "downstream": {...}}``. Every path step is
        ``{"node": {"table", "column", "depth"}, "edge": <original edge or
        null>}``; paths are sorted by ``(edge count, node ids, edge ids)``.
        ``cycle_nodes`` / ``cycle_edges`` identify the nodes and directed
        back-edges that close cycles while every other independent path is
        still returned.
    :raises ValueError: the existing ``InvalidFieldLineageInputError`` /
        ``InvalidFieldLineageQueryError`` for malformed graphs or queries,
        and :class:`LineageNodeNotFoundError`
        (``code == "LINEAGE_NODE_NOT_FOUND"``) for an undeclared target.
    """
    start, edge_dicts, prepared = _field_level_query(
        fields, edges, target, direction, max_depth
    )
    target_ref = {"table": start[0], "column": start[1]}
    return {
        "target": target_ref,
        "direction": direction,
        "max_depth": max_depth,
        "upstream": _build_field_side(
            start, edge_dicts, prepared["upstream_neighbors"], max_depth
        ),
        "downstream": _build_field_side(
            start, edge_dicts, prepared["downstream_neighbors"], max_depth
        ),
    }

